nextflow_process {

    name "Test Process KMERGENIE"
    script "../main.nf"
    process "KMERGENIE"

    tag "modules"
    tag "modules_nfcore"
    tag "kmergenie"

    test("test-kmergenie-sarscov2-illumina") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ], // meta map
				    [
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true),
				        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists: true)
                    ]
				]

                """
            }
        }

        then {
            assertAll(
                { assert process.success  },
                { assert process.out.html },
                { assert process.out.html[0][1] ==~ /.*test_report\.html$/ },
                { assert path(process.out.html[0][1]).getText().contains("Predicted best k: ") },
                { assert path(process.out.log[0][1]).getText().readLines().last().contains("best k: ") },
                { assert snapshot(
                    process.out.histo,
                    process.out.dat,
                    process.out.findAll { key, val -> key.startsWith("versions")},
                ).match() }
            )
        }

    }

    test("test-kmergenie-sarscov2-illumina-stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ], // meta map
				    [
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true),
				        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists: true)
                    ]
				]

                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(
                    process.out,
                    process.out.findAll { key, val -> key.startsWith("versions")},
                ).match() }
            )
        }

    }

}
